draft.sparql:
PREFIX hyu: <urn:hyu-chatbot:vocab:>
SELECT ?from ?through ?credits ?sourcePage ?sourceText WHERE {
  BIND(2025 AS ?entryYear)
  ?rule hyu:appliesToDepartment <urn:query-term:department> ;
        hyu:hasCondition ?condition ;
        hyu:hasRequirement ?requirement .
  ?condition hyu:entryYearFrom ?from ;
             hyu:entryYearThrough ?through .
  FILTER(?from <= ?entryYear && ?entryYear <= ?through)
  ?requirement hyu:creditScope <urn:query-term:credit-scope> ;
               hyu:requiredCredits ?credits ;
               hyu:sourcePage ?sourcePage ;
               hyu:sourceText ?sourceText .
}

PREFIX hyu: <urn:hyu-chatbot:vocab:>
SELECT ?minimumScore ?failingResult ?sourcePage ?sourceText WHERE {
  ?rule a hyu:EvaluationRule ;
        hyu:minimumScore ?minimumScore ;
        hyu:failingResult ?failingResult ;
        hyu:sourcePage ?sourcePage ;
        hyu:sourceText ?sourceText .
  FILTER(?minimumScore = 60)
}

PREFIX hyu: <urn:hyu-chatbot:vocab:>
PREFIX time: <http://www.w3.org/2006/time#>
SELECT ?start ?end ?sourcePage ?sourceText WHERE {
  ?rule hyu:appliesToStudentCategory <urn:query-term:grade-3> ;
        hyu:targetsAdministrativeAction <urn:query-term:mock-registration> ;
        hyu:effectiveDuring ?event ;
        hyu:sourcePage ?sourcePage ;
        hyu:sourceText ?sourceText .
  ?event time:hasBeginning/time:inXSDDateTimeStamp ?start ;
         time:hasEnd/time:inXSDDateTimeStamp ?end .
}

PREFIX hyu: <urn:hyu-chatbot:vocab:>
SELECT ?countBelow ?percentageBelow ?condition ?sourcePage ?sourceText WHERE {
  ?rule a hyu:LimitRule ;
        hyu:targetsCourseCategory <urn:query-term:general-course> ;
        hyu:sourcePage ?sourcePage ;
        hyu:sourceText ?sourceText .
  OPTIONAL { ?rule hyu:closureWhenEnrollmentBelow ?countBelow }
  OPTIONAL { ?rule hyu:closureWhenEnrollmentPercentageBelow ?percentageBelow }
  OPTIONAL { ?rule hyu:hasCondition ?condition }
  FILTER(BOUND(?countBelow) || BOUND(?percentageBelow))
}

PREFIX hyu: <urn:hyu-chatbot:vocab:>
SELECT ?semesterFrom ?semesterThrough ?exception ?exceptionText
       ?sourcePage ?sourceText WHERE {
  ?rule a hyu:RequirementRule ;
        hyu:targetsAdministrativeAction <urn:query-term:course-registration> ;
        hyu:semesterFrom ?semesterFrom ;
        hyu:semesterThrough ?semesterThrough ;
        hyu:sourcePage ?sourcePage ;
        hyu:sourceText ?sourceText .
  FILTER(?semesterFrom <= 8 && 8 <= ?semesterThrough)
  OPTIONAL {
    ?rule hyu:hasException ?exception .
    ?exception hyu:sourceText ?exceptionText .
  }
}
